import{_ as t,o as r,c as e,a8 as s}from"./chunks/framework.BWjTbCIc.js";const u=JSON.parse('{"title":"圣保罗男女中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-a36f85cd","school_zh":"圣保罗男女中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"圣保罗男女中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-SPCC"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-a36f85cd/s1/2022-23-interview.md","filePath":"reports/school-a36f85cd/s1/2022-23-interview.md"}'),p={name:"reports/school-a36f85cd/s1/2022-23-interview.md"};function n(a,o,c,l,g,d){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="圣保罗男女中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">圣保罗男女中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#圣保罗男女中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;圣保罗男女中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-a36f85cd">← 返回圣保罗男女中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-spcc" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-spcc" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-spcc}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分科个人评估</strong></p><p>多位考生分别接受中文、英文、数学及科学问答。一份标注2023年GA的反馈记录全程约37分钟，家长在校外等候；中文先准备约7分钟，再依次接触三位分科老师，英语另到课室，亦有7分钟准备，两位老师分别面见两位学生。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话朗读，粤语问答；另有粤语认读</p><p><strong>准备、朗读与理解</strong></p><p>阅读文章后，用普通话朗读指定段落，再以粤语回答内容、人物性格、修辞及作者观点。有考生回答共9问，前7问已印在材料上，最后2问由老师即场提出；亦问若自己是作者会如何处理，以及最近看的一本中文书。</p><p><strong>字词认读及解释</strong></p><p>认读“蹒跚”“香气四溢”“糟蹋”，解释“一声不吭”“颤巍巍”等。部分反馈还提到成语解释和粤语读音。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章填空及口头追问</strong></p><p>朗读时要自行补出文中留空的词语，有考生遇到约10空；随后解释选择或词义，回答文章问题，发表意见或续写内容。</p><p><strong>器官移植与创意表达</strong></p><p>一篇材料关于器官移植，除理解题外，问若能治疗一种疾病，会选择哪一种。学生记得部分问题没有唯一答案，需要说明理由。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>解题思路与简便运算</strong></p><p>不同反馈记为2至4题，部分以解释思路为主，另有心算。涉及三角形面积、代数及分配律，例如“73×14＝73×10＋73×a”求a，以及用较快捷的方法算“830×23－830×13”。</p><p><strong>图形、统计与倍数关系</strong></p><p>比较两个图形的共同点，证明两三角形面积相等；观察两个圆形统计图，判断学生分布是否相同、总人数是否一定相同并说明原因。另有正方形分成三个三角形，比较面积及线段倍数；具体图形尺寸未保留。</p></blockquote><blockquote><p><strong>科学：</strong> 中文提问，部分记录允许英语回答</p><p><strong>看图解释生活现象</strong></p><p>图片版本包括电脑、盆栽及台灯；管弦乐团演奏；未开封汽水放冷冻格后爆开；观看3D电影；人在水中走路；烤箱。要求观察并解释科学原理，一份3D电影题有约30秒思考。</p><p><strong>具体问题</strong></p><p>离地球最近的恒星是什么；厚玻璃杯遇热水为何容易破裂；能量饮料涉及什么科学原理；哪种气体属于温室气体；降落伞为何能帮助人安全降落；冷气机为何装在较高位置；木、空气和水哪一种传声最快；为何在水中走路更慢、更费力。</p></blockquote><blockquote><p><strong>学生反馈：</strong></p><p><strong>难度感受</strong></p><p>一位考生认为这是自己参加过的面试中题目最难的一所；数学多次要求说明原理，而非仅报出计算结果。</p></blockquote>',14)])])}const h=t(p,[["render",n]]);export{u as __pageData,h as default};
